"""
Nova Cat Plugin
===============

Command:
    nova --cat

A tiny floating pixel cat launcher for Nova.

Features:
    - Uses the supplied pixel-cat artwork
    - Built-in transparent background
    - Subtle breathing animation
    - Eyes follow the desktop cursor
    - Draggable
    - Left click opens `nova --ui`
    - Right click / Escape closes the cat
    - Always on top
    - No external image file required
    - No external Python packages required at runtime

The plugin only launches Nova's existing GUI when clicked.
"""

from __future__ import annotations

import base64
import math
import os
import shutil
import subprocess
import sys
import tkinter as tk

from novatrix.plugin_system import NovaPlugin


# ============================================================================
# CONFIGURATION
# ============================================================================

DISPLAY_SCALE = 2
FRAME_INTERVAL_MS = 120
EYE_UPDATE_MS = 35

PADDING = 8

DRAG_THRESHOLD = 4


# ============================================================================
# EMBEDDED CAT FRAMES
# ============================================================================
#
# The supplied artwork is embedded directly into this file, so the plugin
# remains a single-file application.
#
# The five frames differ by tiny nearest-neighbour vertical squash/stretch
# changes to create a subtle breathing animation.
#

CAT_FRAMES_B64 = [
        '',
        '',
        '',
        '',
        ''
]


# ============================================================================
# FIND NOVA
# ============================================================================

def find_nova_command() -> list[str]:
    """
    Find the installed Nova executable.

    Prefer the `nova` console command. Fall back to the Python module.
    """

    executable = shutil.which("nova")

    if executable:
        return [executable]

    return [
        sys.executable,
        "-m",
        "novatrix.nova_cli",
    ]


# ============================================================================
# LAUNCH NOVA GUI
# ============================================================================

def launch_nova_gui() -> bool:
    """
    Launch Nova's existing GUI.

    No alternate GUI is implemented here.
    """

    command = find_nova_command()

    command.append("--ui")

    try:
        subprocess.Popen(
            command,
            stdin=subprocess.DEVNULL,
            stdout=subprocess.DEVNULL,
            stderr=subprocess.DEVNULL,
            shell=False,
        )

        return True

    except OSError as error:
        print(
            f"[Nova Cat] Could not launch Nova GUI: {error}",
            file=sys.stderr,
            flush=True,
        )
        return False


# ============================================================================
# CAT WINDOW
# ============================================================================

class CatWindow:

    def __init__(self):

        self.root = tk.Tk()

        # ------------------------------------------------------------------
        # Borderless desktop sprite
        # ------------------------------------------------------------------

        self.root.overrideredirect(True)

        self.root.attributes(
            "-topmost",
            True,
        )

        # ------------------------------------------------------------------
        # Decode embedded frames
        # ------------------------------------------------------------------

        self.frames = []

        for encoded in CAT_FRAMES_B64:

            data = base64.b64decode(
                encoded
            )

            image = tk.PhotoImage(
                data=data
            )

            # Pixel-art enlargement.
            if DISPLAY_SCALE > 1:

                image = image.zoom(
                    DISPLAY_SCALE,
                    DISPLAY_SCALE,
                )

            self.frames.append(
                image
            )

        self.frame_index = 0

        self.current_image = self.frames[0]

        self.image_width = self.current_image.width()
        self.image_height = self.current_image.height()

        self.window_width = (
            self.image_width
            + PADDING * 2
        )

        self.window_height = (
            self.image_height
            + PADDING * 2
        )

        # ------------------------------------------------------------------
        # Transparent window background
        # ------------------------------------------------------------------

        self.transparent = "#00ff00"

        try:

            self.root.configure(
                bg=self.transparent
            )

            self.root.attributes(
                "-transparentcolor",
                self.transparent,
            )

        except tk.TclError:

            # Fallback for environments where Tk's transparentcolor is not
            # available.
            self.transparent = "#000000"

            self.root.configure(
                bg=self.transparent
            )

        # ------------------------------------------------------------------
        # Position
        # ------------------------------------------------------------------

        self._position_bottom_right()

        # ------------------------------------------------------------------
        # Canvas
        # ------------------------------------------------------------------

        self.canvas = tk.Canvas(
            self.root,
            width=self.window_width,
            height=self.window_height,
            bg=self.transparent,
            highlightthickness=0,
            borderwidth=0,
            cursor="hand2",
        )

        self.canvas.pack()

        # ------------------------------------------------------------------
        # Cat image
        # ------------------------------------------------------------------

        self.cat_image_item = self.canvas.create_image(
            self.window_width // 2,
            self.window_height // 2,
            image=self.current_image,
            anchor="center",
            tags=("cat",),
        )

        # ------------------------------------------------------------------
        # Eye overlay
        # ------------------------------------------------------------------
        #
        # Relative to the cropped source image, the two eye positions are
        # approximately here. They are updated from the actual desktop
        # cursor position.
        #

        self.eye_centers_base = [
            (43.0, 27.0),
            (56.0, 27.0),
        ]

        self.pupil_items = []

        # ------------------------------------------------------------------
        # Interaction state
        # ------------------------------------------------------------------

        self.dragging = False

        self.mouse_moved = False

        self.drag_start_x = 0
        self.drag_start_y = 0

        self.window_start_x = 0
        self.window_start_y = 0

        # ------------------------------------------------------------------
        # Mouse bindings
        # ------------------------------------------------------------------

        self.canvas.bind(
            "<ButtonPress-1>",
            self._mouse_down,
        )

        self.canvas.bind(
            "<B1-Motion>",
            self._mouse_drag,
        )

        self.canvas.bind(
            "<ButtonRelease-1>",
            self._mouse_up,
        )

        self.canvas.bind(
            "<Button-3>",
            self._close,
        )

        self.root.bind(
            "<Escape>",
            self._close,
        )

        # ------------------------------------------------------------------
        # Start animation
        # ------------------------------------------------------------------

        self._animate_breathing()
        self._update_eyes()

    # ======================================================================
    # POSITION
    # ======================================================================

    def _position_bottom_right(self):

        screen_width = (
            self.root.winfo_screenwidth()
        )

        screen_height = (
            self.root.winfo_screenheight()
        )

        x = (
            screen_width
            - self.window_width
            - 35
        )

        y = (
            screen_height
            - self.window_height
            - 75
        )

        self.root.geometry(
            f"{self.window_width}x{self.window_height}"
            f"+{x}+{y}"
        )

    # ======================================================================
    # BREATHING ANIMATION
    # ======================================================================

    def _animate_breathing(self):

        if not self.root.winfo_exists():
            return

        self.frame_index = (
            self.frame_index + 1
        ) % len(self.frames)

        self.current_image = (
            self.frames[self.frame_index]
        )

        self.canvas.itemconfigure(
            self.cat_image_item,
            image=self.current_image,
        )

        self.root.after(
            FRAME_INTERVAL_MS,
            self._animate_breathing,
        )

    # ======================================================================
    # EYE TRACKING
    # ======================================================================

    def _update_eyes(self):

        if not self.root.winfo_exists():
            return

        # Remove old pupils.
        for item in self.pupil_items:

            self.canvas.delete(
                item
            )

        self.pupil_items.clear()

        # Use canvas-relative pointer coordinates so the eye overlay stays
        # aligned with the cat regardless of the window's screen position.
        mouse_x = (
            self.canvas.winfo_pointerx()
            - self.canvas.winfo_rootx()
        )

        mouse_y = (
            self.canvas.winfo_pointery()
            - self.canvas.winfo_rooty()
        )

        # The embedded image uses a base cropped size and is enlarged at
        # runtime. Translate the eye coordinates accordingly.
        for base_x, base_y in self.eye_centers_base:

            eye_x = (
                PADDING
                + base_x * DISPLAY_SCALE
            )

            eye_y = (
                PADDING
                + base_y * DISPLAY_SCALE
            )

            dx = (
                mouse_x
                - eye_x
            )

            dy = (
                mouse_y
                - eye_y
            )

            distance = math.hypot(
                dx,
                dy,
            )

            if distance > 0:

                dx /= distance
                dy /= distance

            # Very small movement keeps the original pixel-art expression.
            pupil_distance = (
                1.6 * DISPLAY_SCALE
            )

            px = (
                eye_x
                + dx * pupil_distance
            )

            py = (
                eye_y
                + dy * pupil_distance
            )

            # Small hard-edged square pupil for a pixel-art look.
            half_size = (
                1.5 * DISPLAY_SCALE
            )

            pupil = self.canvas.create_rectangle(
                round(px - half_size),
                round(py - half_size),
                round(px + half_size),
                round(py + half_size),
                fill="#111111",
                outline="#111111",
                tags=("eyes",),
            )

            self.pupil_items.append(
                pupil
            )

        # Keep eye overlay above the cat.
        self.canvas.tag_raise(
            "eyes"
        )

        self.root.after(
            EYE_UPDATE_MS,
            self._update_eyes,
        )

    # ======================================================================
    # DRAGGING
    # ======================================================================

    def _mouse_down(
        self,
        event,
    ):

        self.dragging = True

        self.mouse_moved = False

        self.drag_start_x = (
            event.x_root
        )

        self.drag_start_y = (
            event.y_root
        )

        self.window_start_x = (
            self.root.winfo_x()
        )

        self.window_start_y = (
            self.root.winfo_y()
        )

    def _mouse_drag(
        self,
        event,
    ):

        if not self.dragging:
            return

        dx = (
            event.x_root
            - self.drag_start_x
        )

        dy = (
            event.y_root
            - self.drag_start_y
        )

        if (
            abs(dx) >= DRAG_THRESHOLD
            or abs(dy) >= DRAG_THRESHOLD
        ):

            self.mouse_moved = True

        new_x = (
            self.window_start_x
            + dx
        )

        new_y = (
            self.window_start_y
            + dy
        )

        self.root.geometry(
            f"{self.window_width}x{self.window_height}"
            f"+{new_x}+{new_y}"
        )

    def _mouse_up(
        self,
        event,
    ):

        del event

        self.dragging = False

        # A normal click opens Nova.
        # A drag only moves the cat.
        if not self.mouse_moved:

            if launch_nova_gui():

                self.root.destroy()

    # ======================================================================
    # CLOSE
    # ======================================================================

    def _close(
        self,
        event=None,
    ):

        del event

        self.root.destroy()

    # ======================================================================
    # RUN
    # ======================================================================

    def run(self):

        self.root.mainloop()


# ============================================================================
# CLI CALLBACK
# ============================================================================

def run_cat(
    args,
    runtime,
):

    del args
    del runtime

    cat = CatWindow()

    cat.run()


# ============================================================================
# NOVA PLUGIN
# ============================================================================

class CatPlugin(NovaPlugin):

    name = "cat"
    version = "1.2.0"
    description = (
        "Summon an animated draggable pixel cat that launches Nova."
    )
    plugin_api_version = 1

    def register(
        self,
        nova_runtime,
    ):

        nova_runtime.register_cli_command(
            name="cat",
            callback=run_cat,
            help_text=(
                "Summon an animated pixel cat that launches Nova GUI."
            ),
            action="store_true",
        )


# ============================================================================
# REQUIRED PLUGIN EXPORT
# ============================================================================

plugin = CatPlugin()
